175	fn powc(a: Complex64, exp: Complex64) -> Complex64 {
176	    let (r, theta) = a.to_polar();
177	    if r.is_zero() {
178	        return Complex64::new(r, r);
179	    }
180	    Complex64::from_polar(
181	        r.powf(exp.re) * (-exp.im * theta).exp(),
182	        exp.re * theta + exp.im * r.ln(),
183	    )
